const before = await client.items.find<Schema.Article>("article-1", { nested: true });
const originalBody = JSON.stringify(before.body);
if (!before.body.en) throw new Error("English Structured Text is missing.");
let greetingMatches = 0;
let blockMatches = 0;
const english = mapNodes(before.body.en, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingMatches += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    blockMatches += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        ...node.item.attributes,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});
if (greetingMatches !== 1 || blockMatches !== 1) {
  throw new Error("Expected exactly one greeting span and one image block.");
}
english.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});
if (JSON.stringify(before.body) !== originalBody) {
  throw new Error("The original snapshot was unexpectedly modified.");
}
const expectedBody = { ...before.body, en: english };
await client.items.update<Schema.Article>(before.id, {
  body: expectedBody,
  meta: { current_version: before.meta.current_version },
});
const after = await client.items.find<Schema.Article>(before.id, { nested: true });
if (JSON.stringify(after.body) !== JSON.stringify(expectedBody)) {
  throw new Error("Saved Structured Text differs from the expected content.");
}
if (after.id !== before.id || after.title !== before.title || after.untouched !== before.untouched) {
  throw new Error("An unrelated record field changed.");
}
if (JSON.stringify(after.body.it) !== JSON.stringify(before.body.it)) {
  throw new Error("Italian locale changed.");
}
if (after.meta.status !== "draft") {
  throw new Error("Expected the article to remain a draft.");
}
console.log({ verified: true, article: after });

