    en: {
      schema: "dast",
      document: {
        type: "root",
        children: [
          { type: "paragraph", children: [
            { type: "span", value: "Welcome reader", marks: ["strong"] },
            { type: "span", value: " — " },
            { type: "link", url: "https://example.test/help", children: [{ type: "span", value: "Help" }] },
          ] },
          { type: "block", item: {
            id: "block-1", type: "item", __itemTypeId: "image-block",
            attributes: { caption: "Summer portrait", image: null },
          } },
          { type: "paragraph", children: [{ type: "span", value: "See you soon." }] },
        ],
      },
    },
    it: {
      schema: "dast",
      document: { type: "root", children: [
        { type: "paragraph", children: [{ type: "span", value: "Ciao lettore" }] },
      ] },
