const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true, version: "current" });
if (!currentItem.body.en) throw new Error("English Structured Text is missing.");
const originalEnglish = JSON.stringify(currentItem.body.en);
const originalItalian = JSON.stringify(currentItem.body.it);
let greetingCount = 0;
let blockCount = 0;
const content = mapNodes(currentItem.body.en, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingCount += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    blockCount += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        ...node.item.attributes,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});
if (greetingCount !== 1 || blockCount !== 1) {
  throw new Error("Expected exactly one greeting span and one block-1; no update made.");
}
if (JSON.stringify(currentItem.body.en) !== originalEnglish) {
  throw new Error("The original English snapshot was unexpectedly modified.");
}
content.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});
const body: FieldValueInRequest<typeof currentItem, "body"> = { ...currentItem.body, en: content };
const expectedFields = JSON.stringify({ ...currentItem, body, meta: undefined });
await client.items.update<Schema.Article>(currentItem.id, {
  body,
  meta: { current_version: currentItem.meta.current_version },
});
const saved = await client.items.find<Schema.Article>(currentItem.id, { nested: true, version: "current" });
if (JSON.stringify({ ...saved, meta: undefined }) !== expectedFields) {
  throw new Error("Saved content differs from the expected record.");
}
if (JSON.stringify(saved.body.it) !== originalItalian) {
  throw new Error("Italian locale changed unexpectedly.");
}
if (saved.meta.status !== currentItem.meta.status || saved.meta.status !== "draft") {
  throw new Error("The record did not retain its draft status.");
}
console.log({
  id: saved.id,
  status: saved.meta.status,
  current_version: saved.meta.current_version,
  verified: "Three English edits saved; all other nodes, fields, marks, link, block identity and image, and Italian locale preserved.",
  article: saved,
});

const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true, version: "current" });
const originalSnapshot = JSON.stringify(currentItem);
if (!currentItem.body.en) throw new Error("English Structured Text is missing.");

let greetingCount = 0;
let imageBlockCount = 0;
const content = mapNodes(currentItem.body.en, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingCount += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    imageBlockCount += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        ...node.item.attributes,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});
if (greetingCount !== 1 || imageBlockCount !== 1) {
  throw new Error("Expected exactly one greeting span and one image block block-1.");
}
content.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});
if (JSON.stringify(currentItem) !== originalSnapshot) {
  throw new Error("The original record snapshot was unexpectedly modified before saving.");
}

const body: FieldValueInRequest<typeof currentItem, "body"> = {
  ...currentItem.body,
  en: content,
};
const { meta: originalMeta, ...originalFields } = currentItem;
const expectedFields = { ...originalFields, body };

await client.items.update<Schema.Article>(currentItem.id, {
  body,
  meta: { current_version: originalMeta.current_version },
});

const saved = await client.items.find<Schema.Article>(currentItem.id, { nested: true, version: "current" });
const { meta: savedMeta, ...savedFields } = saved;
if (JSON.stringify(savedFields) !== JSON.stringify(expectedFields)) {
  throw new Error("The saved article does not match the expected content. Inspect before retrying.");
}
if (savedMeta.status !== originalMeta.status) {
  throw new Error("Publication status changed unexpectedly. Inspect before taking further action.");
}
console.log(JSON.stringify({ verified: true, article: saved }));

const currentItem = await client.items.find<Schema.Article>("article-1", { nested: true, version: "current" });
if (!currentItem.body.en) throw new Error("English Structured Text is missing.");

const originalEnglish = JSON.stringify(currentItem.body.en);
const originalItalian = JSON.stringify(currentItem.body.it);
const { body: originalBody, meta: originalMeta, ...originalOtherFields } = currentItem;
let greetingMatches = 0;
let blockMatches = 0;

const content: NonNullable<FieldValueInRequest<typeof currentItem, "body">["en"]> =
  mapNodes(currentItem.body.en, (node) => {
    if (isSpan(node) && node.value === "Hello reader") {
      greetingMatches += 1;
      return { ...node, value: "Welcome reader" };
    }
    if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
      blockMatches += 1;
      return {
        ...node,
        item: buildBlockRecord<Schema.ImageBlock>({
          ...node.item.attributes,
          id: node.item.id,
          caption: "Summer portrait",
        }),
      };
    }
    return node;
  });

if (greetingMatches !== 1 || blockMatches !== 1) {
  throw new Error("Expected exactly one greeting span and one block-1; no update sent.");
}
content.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});
if (JSON.stringify(currentItem.body.en) !== originalEnglish) {
  throw new Error("The original English snapshot changed during preparation; no update sent.");
}

const body: FieldValueInRequest<typeof currentItem, "body"> = { ...currentItem.body, en: content };
const expectedBody = JSON.stringify(body);

await client.items.update<Schema.Article>(currentItem.id, {
  body,
  meta: { current_version: currentItem.meta.current_version },
});
const saved = await client.items.find<Schema.Article>(currentItem.id, { nested: true, version: "current" });
const { body: savedBody, meta: savedMeta, ...savedOtherFields } = saved;
if (JSON.stringify(savedBody) !== expectedBody) {
  throw new Error("Saved Structured Text differs from the intended result; inspect before any retry.");
}
if (JSON.stringify(savedBody.it) !== originalItalian ||
    JSON.stringify(savedOtherFields) !== JSON.stringify(originalOtherFields) ||
    savedMeta.status !== originalMeta.status) {
  throw new Error("Preservation verification failed; inspect before any retry.");
}
console.log({ id: saved.id, status: savedMeta.status, verified: true, record: saved });

